public class InnerClusterKubeControllerManagerConfigFactory(Action<Humidifier.EKS.ClusterTypes.KubeControllerManagerConfig> factoryAction = null) : SubResourceFactory<Humidifier.EKS.ClusterTypes.KubeControllerManagerConfig>
{

    internal InnerClusterPodGcControllerConfigFactory PodGcControllerConfigFactory { get; set; }

    internal InnerClusterHorizontalPodAutoscalerControllerConfigFactory HorizontalPodAutoscalerControllerConfigFactory { get; set; }

    protected override Humidifier.EKS.ClusterTypes.KubeControllerManagerConfig Create()
    {
        var kubeControllerManagerConfigResult = CreateKubeControllerManagerConfig();
        factoryAction?.Invoke(kubeControllerManagerConfigResult);

        return kubeControllerManagerConfigResult;
    }

    private Humidifier.EKS.ClusterTypes.KubeControllerManagerConfig CreateKubeControllerManagerConfig()
    {
        var kubeControllerManagerConfigResult = new Humidifier.EKS.ClusterTypes.KubeControllerManagerConfig();

        return kubeControllerManagerConfigResult;
    }
    public override void CreateChildren(Humidifier.EKS.ClusterTypes.KubeControllerManagerConfig result)
    {
        base.CreateChildren(result);

        result.PodGcControllerConfig ??= PodGcControllerConfigFactory?.Build();
        result.HorizontalPodAutoscalerControllerConfig ??= HorizontalPodAutoscalerControllerConfigFactory?.Build();
    }

} // End Of Class

